SELECT t2.drugname AS drugname FROM (SELECT patient.uniquepid AS uniquepid, treatment.treatmenttime AS treatmenttime, patient.patienthealthsystemstayid AS patienthealthsystemstayid FROM treatment AS treatment JOIN patient AS patient ON treatment.patientunitstayid = patient.patientunitstayid WHERE patient.patienthealthsystemstayid IN (SELECT patient.patienthealthsystemstayid AS patienthealthsystemstayid FROM patient AS patient WHERE patient.uniquepid = '005-66412') AND treatment.treatmentname = '静脉血栓栓塞症预防——弹力袜' AND STRFTIME('%y-%m', treatment.treatmenttime) <= '2105-09') AS t1 JOIN (SELECT patient.uniquepid AS uniquepid, medication.drugname AS drugname, medication.drugstarttime AS drugstarttime, patient.patienthealthsystemstayid AS patienthealthsystemstayid FROM medication AS medication JOIN patient AS patient ON medication.patientunitstayid = patient.patientunitstayid WHERE patient.patienthealthsystemstayid IN (SELECT patient.patienthealthsystemstayid AS patienthealthsystemstayid FROM patient AS patient WHERE patient.uniquepid = '005-66412') AND STRFTIME('%y-%m', medication.drugstarttime) <= '2105-09') AS t2 ON t1.uniquepid = t2.uniquepid WHERE t1.treatmenttime < t2.drugstarttime AND t1.patienthealthsystemstayid = t2.patienthealthsystemstayid	eicu
