SELECT SUM(CASE WHEN patient.hospitaldischargestatus = '存活' THEN 1 WHEN STRFTIME('%j', patient.hospitaldischargetime) - STRFTIME('%j', t2.diagnosistime) > 2 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS _col_0 FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosistime AS diagnosistime FROM (SELECT patient.uniquepid AS uniquepid, diagnosis.diagnosistime AS diagnosistime FROM diagnosis AS diagnosis JOIN patient AS patient ON diagnosis.patientunitstayid = patient.patientunitstayid WHERE diagnosis.diagnosisname = 'sepsis - sepsis with single organ dysfunction- metabolic encephalopathy' GROUP BY patient.uniquepid HAVING MIN(diagnosis.diagnosistime) = diagnosis.diagnosistime) AS t1 WHERE STRFTIME('%j', CURRENT_TIME) - STRFTIME('%j', t1.diagnosistime) > 2 * 365) AS t2 JOIN patient AS patient ON t2.uniquepid = patient.uniquepid	eicu
SELECT SUM(CASE WHEN patient.hospitaldischargestatus = '存活' THEN 1 WHEN STRFTIME('%j', patient.hospitaldischargetime) - STRFTIME('%j', t4.diagnosistime) > 3 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS _col_0 FROM (SELECT t2.uniquepid AS uniquepid, t2.diagnosistime AS diagnosistime FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosistime AS diagnosistime FROM (SELECT patient.uniquepid AS uniquepid, diagnosis.diagnosistime AS diagnosistime FROM diagnosis AS diagnosis JOIN patient AS patient ON diagnosis.patientunitstayid = patient.patientunitstayid WHERE diagnosis.diagnosisname = 'valvular stenosis' GROUP BY patient.uniquepid HAVING MIN(diagnosis.diagnosistime) = diagnosis.diagnosistime) AS t1) AS t2 JOIN (SELECT patient.uniquepid AS uniquepid, medication.drugstarttime AS drugstarttime FROM medication AS medication JOIN patient AS patient ON medication.patientunitstayid = patient.patientunitstayid WHERE medication.drugname = 'potassium chloride crys er 20 meq po tbcr') AS t3 ON t2.uniquepid = t3.uniquepid WHERE t2.diagnosistime < t3.drugstarttime) AS t4 JOIN patient AS patient ON t4.uniquepid = patient.uniquepid	eicu
SELECT SUM(CASE WHEN patient.hospitaldischargestatus = '存活' THEN 1 WHEN STRFTIME('%j', patient.hospitaldischargetime) - STRFTIME('%j', t4.diagnosistime) > 2 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS _col_0 FROM (SELECT t2.uniquepid AS uniquepid, t2.diagnosistime AS diagnosistime FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosistime AS diagnosistime FROM (SELECT patient.uniquepid AS uniquepid, diagnosis.diagnosistime AS diagnosistime FROM diagnosis AS diagnosis JOIN patient AS patient ON diagnosis.patientunitstayid = patient.patientunitstayid WHERE diagnosis.diagnosisname = 'malignancy' GROUP BY patient.uniquepid HAVING MIN(diagnosis.diagnosistime) = diagnosis.diagnosistime) AS t1) AS t2 JOIN (SELECT patient.uniquepid AS uniquepid, medication.drugstarttime AS drugstarttime FROM medication AS medication JOIN patient AS patient ON medication.patientunitstayid = patient.patientunitstayid WHERE medication.drugname = 'piperacillin-tazobactam 3.375 g ivpb') AS t3 ON t2.uniquepid = t3.uniquepid WHERE t2.diagnosistime < t3.drugstarttime) AS t4 JOIN patient AS patient ON t4.uniquepid = patient.uniquepid	eicu
SELECT t4.diagnosisname AS diagnosisname FROM (SELECT t3.diagnosisname AS diagnosisname, DENSE_RANK() OVER (ORDER BY t3.c1 DESC) AS c2 FROM (SELECT t2.diagnosisname AS diagnosisname, 100 - SUM(CASE WHEN patient.hospitaldischargestatus = '存活' THEN 1 WHEN STRFTIME('%j', patient.hospitaldischargetime) - STRFTIME('%j', t2.diagnosistime) > 3 * 365 THEN 1 ELSE 0 END) * 100 / COUNT(*) AS c1 FROM (SELECT t1.uniquepid AS uniquepid, t1.diagnosisname AS diagnosisname, t1.diagnosistime AS diagnosistime FROM (SELECT patient.uniquepid AS uniquepid, diagnosis.diagnosisname AS diagnosisname, diagnosis.diagnosistime AS diagnosistime FROM diagnosis AS diagnosis JOIN patient AS patient ON diagnosis.patientunitstayid = patient.patientunitstayid GROUP BY patient.uniquepid, diagnosis.diagnosisname HAVING MIN(diagnosis.diagnosistime) = diagnosis.diagnosistime) AS t1 WHERE STRFTIME('%j', CURRENT_TIME) - STRFTIME('%j', t1.diagnosistime) > 3 * 365) AS t2 JOIN patient AS patient ON t2.uniquepid = patient.uniquepid GROUP BY t2.diagnosisname) AS t3) AS t4 WHERE t4.c2 <= 5	eicu
