SELECT COUNT(DISTINCT t1.uniquepid) AS _col_0 FROM (SELECT patient.uniquepid AS uniquepid, treatment.treatmenttime AS treatmenttime FROM treatment AS treatment JOIN patient AS patient ON treatment.patientunitstayid = patient.patientunitstayid WHERE treatment.treatmentname = '支气管镜检查——伴支气管肺泡灌洗（BAL）' AND STRFTIME('%y', treatment.treatmenttime) >= '2105') AS t1 JOIN (SELECT patient.uniquepid AS uniquepid, treatment.treatmenttime AS treatmenttime FROM treatment AS treatment JOIN patient AS patient ON treatment.patientunitstayid = patient.patientunitstayid WHERE treatment.treatmentname = '应激性溃疡预防——雷尼替丁' AND STRFTIME('%y', treatment.treatmenttime) >= '2105') AS t2 ON TRUE WHERE t1.treatmenttime < t2.treatmenttime AND DATETIME(t2.treatmenttime) BETWEEN DATETIME(t1.treatmenttime) AND DATETIME(t1.treatmenttime, '+2 month')	eicu
